
'use strict';

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const zlib = require('node:zlib');

const PLUGIN_NAME = 'dsh-plugin-thesis-format-assistant';
const SKILL_NAME = 'thesis-format-assistant';
const PAYLOAD_VERSION = '5.4.0';
const PAYLOAD = '';

function readVersion(dir) {
  try {
    return fs.readFileSync(path.join(dir, 'VERSION'), 'utf8').trim();
  } catch {
    return null;
  }
}

function installSkill(ctx) {
  const dshHome = process.env.DSH_HOME || path.join(os.homedir(), '.dsh');
  const skillsRoot = path.join(dshHome, 'skills');
  const target = path.join(skillsRoot, SKILL_NAME);
  if (readVersion(target) === PAYLOAD_VERSION) {
    ctx?.logger?.info?.(`[${PLUGIN_NAME}] skill ${PAYLOAD_VERSION} already installed`);
    return;
  }

  let files;
  try {
    const raw = zlib.gunzipSync(Buffer.from(PAYLOAD, 'base64')).toString('utf8');
    files = JSON.parse(raw);
  } catch (error) {
    ctx?.logger?.warn?.(`[${PLUGIN_NAME}] payload is invalid: ${error?.message || error}`);
    return;
  }

  const staging = `${target}.installing-${process.pid}`;
  try {
    fs.mkdirSync(skillsRoot, { recursive: true });
    fs.rmSync(staging, { recursive: true, force: true });
    fs.mkdirSync(staging, { recursive: true });
    for (const [rel, encoded] of Object.entries(files)) {
      if (rel.startsWith('/') || rel.split('/').includes('..')) {
        throw new Error(`unsafe bundled path: ${rel}`);
      }
      const destination = path.join(staging, ...rel.split('/'));
      fs.mkdirSync(path.dirname(destination), { recursive: true });
      fs.writeFileSync(destination, Buffer.from(encoded, 'base64'));
    }
    fs.rmSync(target, { recursive: true, force: true });
    fs.renameSync(staging, target);
    ctx?.logger?.info?.(`[${PLUGIN_NAME}] installed ${SKILL_NAME} ${PAYLOAD_VERSION}`);
  } catch (error) {
    fs.rmSync(staging, { recursive: true, force: true });
    ctx?.logger?.warn?.(`[${PLUGIN_NAME}] could not install skill: ${error?.message || error}`);
  }
}

module.exports = {
  name: PLUGIN_NAME,
  apply(ctx) {
    installSkill(ctx);
  },
  installSkill,
};
